import { useRef, useState } from 'react';
import type { ReactNode } from 'react';

type Values = {
  orgName: string;
  contactName: string;
  contactEmail: string;
  sector: string;
  summary: string;
  projectType: string;
  startDate: string;
  budget: string;
  funding: string;
};

const empty: Values = {
  orgName: '',
  contactName: '',
  contactEmail: '',
  sector: '',
  summary: '',
  projectType: '',
  startDate: '',
  budget: '',
  funding: '',
};

type Field = { key: keyof Values; label: string };

const steps: { title: string; required: Field[] }[] = [
  {
    title: 'Organisation',
    required: [
      { key: 'orgName', label: 'Organisation name' },
      { key: 'contactName', label: 'Contact name' },
      { key: 'contactEmail', label: 'Contact email' },
    ],
  },
  {
    title: 'Scope',
    required: [
      { key: 'projectType', label: 'Project type' },
      { key: 'summary', label: 'Project summary' },
    ],
  },
  {
    title: 'Budget',
    required: [
      { key: 'budget', label: 'Budget range' },
      { key: 'funding', label: 'Funding source' },
    ],
  },
  { title: 'Review', required: [] },
];

const projectTypes = [
  { id: 'build', title: 'Build', note: 'A new system or capability' },
  { id: 'assess', title: 'Assess', note: 'Review of an existing system or risk' },
  { id: 'integrate', title: 'Integrate', note: 'Connect tools or data already in place' },
];

const budgets = ['Under 50,000', '50,000 – 150,000', '150,000 – 500,000', 'Over 500,000'];

function validate(step: number, v: Values): Partial<Record<keyof Values, string>> {
  const errs: Partial<Record<keyof Values, string>> = {};
  for (const f of steps[step].required) {
    if (!v[f.key].trim()) errs[f.key] = `${f.label} is required`;
  }
  if (!errs.contactEmail && step === 0 && v.contactEmail && !/^\S+@\S+\.\S+$/.test(v.contactEmail)) {
    errs.contactEmail = 'Enter an email address like name@example.com';
  }
  return errs;
}

function FieldWrap(props: {
  id: string;
  label: string;
  required?: boolean;
  error?: string;
  hint?: string;
  children: ReactNode;
}) {
  return (
    <div className="stack" style={{ gap: 'var(--space-2)' }}>
      <label htmlFor={props.id}>
        {props.label}
        {props.required ? '' : ' (optional)'}
      </label>
      {props.children}
      {props.hint && !props.error && (
        <span id={`${props.id}-msg`} className="muted">
          {props.hint}
        </span>
      )}
      {props.error && (
        <span id={`${props.id}-msg`} role="alert" style={{ color: 'var(--color-danger-700)' }}>
          {props.error}
        </span>
      )}
    </div>
  );
}

export function App() {
  const [step, setStep] = useState(0);
  const [values, setValues] = useState<Values>(empty);
  const [errors, setErrors] = useState<Partial<Record<keyof Values, string>>>({});
  const [done, setDone] = useState(false);
  const headingRef = useRef<HTMLHeadingElement>(null);

  const set = (k: keyof Values, val: string) => {
    setValues((v) => ({ ...v, [k]: val }));
    if (errors[k]) setErrors((e) => ({ ...e, [k]: undefined }));
  };

  const goto = (n: number) => {
    setStep(n);
    setErrors({});
    requestAnimationFrame(() => headingRef.current?.focus());
  };

  const next = () => {
    const errs = validate(step, values);
    if (Object.keys(errs).length) {
      setErrors(errs);
      requestAnimationFrame(() => {
        const first = Object.keys(errs)[0];
        document.getElementById(`f-${first}`)?.focus();
      });
      return;
    }
    goto(step + 1);
  };

  // Steps ahead of the first incomplete one stay unreachable from the list.
  const canReach = (n: number) => {
    for (let i = 0; i < n; i++) if (Object.keys(validate(i, values)).length) return false;
    return true;
  };

  const inputProps = (k: keyof Values, required = true) => ({
    id: `f-${k}`,
    value: values[k],
    required,
    'aria-required': required,
    'aria-invalid': errors[k] ? true : undefined,
    'aria-describedby': errors[k] ? `f-${k}-msg` : undefined,
    onChange: (e: { target: { value: string } }) => set(k, e.target.value),
  });

  if (done) {
    return (
      <main className="container section">
        <div className="state" data-tone="success">
          <h1 className="state-title">Intake submitted</h1>
          <p className="state-body">
            {values.orgName} — we will contact {values.contactName} at {values.contactEmail}.
          </p>
          <div className="state-actions">
            <button
              type="button"
              className="btn btn-secondary"
              onClick={() => {
                setValues(empty);
                setDone(false);
                setStep(0);
              }}
            >
              Start another
            </button>
          </div>
        </div>
      </main>
    );
  }

  const errorList = Object.entries(errors).filter(([, m]) => m) as [string, string][];
  const last = step === steps.length - 1;

  return (
    <main className="container section">
      <div className="flow">
        <nav className="flow-rail" aria-label="Intake steps">
          <ol className="stepper stepper-vertical">
            {steps.map((s, i) => (
              <li
                key={s.title}
                className="step"
                data-state={i < step ? 'complete' : i === step ? 'current' : 'upcoming'}
                aria-current={i === step ? 'step' : undefined}
              >
                <button
                  type="button"
                  className="btn btn-ghost"
                  disabled={i !== step && !canReach(i)}
                  onClick={() => goto(i)}
                >
                  <span className="step-marker">{i + 1}</span>
                  <span className="step-label">{s.title}</span>
                </button>
              </li>
            ))}
          </ol>
        </nav>

        <form
          className="flow-main"
          noValidate
          onSubmit={(e) => {
            e.preventDefault();
            if (last) setDone(true);
            else next();
          }}
        >
          <header className="flow-header">
            <h1 ref={headingRef} tabIndex={-1}>
              {steps[step].title}
            </h1>
            <p className="muted">
              Step {step + 1} of {steps.length}
            </p>
          </header>

          <div className="flow-content">
            {errorList.length > 0 && (
              <div className="error-summary" role="alert">
                <p>Complete the required fields to continue:</p>
                <ul>
                  {errorList.map(([k, m]) => (
                    <li key={k}>
                      <a href={`#f-${k}`}>{m}</a>
                    </li>
                  ))}
                </ul>
              </div>
            )}

            <div className="flow-fields stack">
              {step === 0 && (
                <>
                  <FieldWrap id="f-orgName" label="Organisation name" required error={errors.orgName}>
                    <input className="input" autoComplete="organization" {...inputProps('orgName')} />
                  </FieldWrap>
                  <FieldWrap id="f-contactName" label="Contact name" required error={errors.contactName}>
                    <input className="input" autoComplete="name" {...inputProps('contactName')} />
                  </FieldWrap>
                  <FieldWrap id="f-contactEmail" label="Contact email" required error={errors.contactEmail}>
                    <input className="input" type="email" autoComplete="email" {...inputProps('contactEmail')} />
                  </FieldWrap>
                  <FieldWrap id="f-sector" label="Sector">
                    <input className="input" {...inputProps('sector', false)} />
                  </FieldWrap>
                </>
              )}

              {step === 1 && (
                <>
                  <fieldset className="stack" style={{ border: 0, padding: 0, margin: 0 }}>
                    <legend>Project type</legend>
                    <div
                      className="radio-cards"
                      role="radiogroup"
                      aria-label="Project type"
                      aria-required="true"
                    >
                      {projectTypes.map((t, i) => (
                        <label key={t.id} className="radio-card">
                          <input
                            id={i === 0 ? 'f-projectType' : undefined}
                            type="radio"
                            name="projectType"
                            value={t.id}
                            checked={values.projectType === t.id}
                            onChange={() => set('projectType', t.id)}
                          />
                          <span className="radio-card-title">{t.title}</span>
                          <span className="radio-card-note">{t.note}</span>
                        </label>
                      ))}
                    </div>
                    {errors.projectType && (
                      <span role="alert" style={{ color: 'var(--color-danger-700)' }}>
                        {errors.projectType}
                      </span>
                    )}
                  </fieldset>
                  <FieldWrap
                    id="f-summary"
                    label="Project summary"
                    required
                    error={errors.summary}
                    hint="What should change once this project is delivered?"
                  >
                    <textarea className="input" rows={5} {...inputProps('summary')} />
                  </FieldWrap>
                </>
              )}

              {step === 2 && (
                <>
                  <FieldWrap id="f-budget" label="Budget range" required error={errors.budget}>
                    <select className="input" {...inputProps('budget')}>
                      <option value="">Select a range</option>
                      {budgets.map((b) => (
                        <option key={b} value={b}>
                          {b}
                        </option>
                      ))}
                    </select>
                  </FieldWrap>
                  <FieldWrap id="f-funding" label="Funding source" required error={errors.funding}>
                    <input className="input" {...inputProps('funding')} />
                  </FieldWrap>
                  <FieldWrap id="f-startDate" label="Preferred start date">
                    <input className="input" type="date" {...inputProps('startDate', false)} />
                  </FieldWrap>
                </>
              )}

              {step === 3 && (
                <div className="summary">
                  {[
                    ['Organisation', values.orgName],
                    ['Contact', `${values.contactName} · ${values.contactEmail}`],
                    ['Sector', values.sector || 'Not given'],
                    ['Project type', projectTypes.find((t) => t.id === values.projectType)?.title ?? ''],
                    ['Summary', values.summary],
                    ['Budget range', values.budget],
                    ['Funding source', values.funding],
                    ['Preferred start', values.startDate || 'Not given'],
                  ].map(([k, v]) => (
                    <div key={k} className="summary-row">
                      <span className="muted">{k}</span>
                      <span>{v}</span>
                    </div>
                  ))}
                </div>
              )}
            </div>
          </div>

          <footer className="flow-footer">
            <button type="button" className="btn btn-secondary" disabled={step === 0} onClick={() => goto(step - 1)}>
              Back
            </button>
            <button type="submit" className="btn btn-primary">
              {last ? 'Submit' : 'Next'}
            </button>
          </footer>
        </form>
      </div>
    </main>
  );
}
